    recheckOperatorPendingPaymentAttempt: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                merchantReference: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Existing attempt rechecked by reference. A verified late payment is recorded for refund review. */
            200: {
                headers: {
                    "Cache-Control"?: "no-store";
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @enum {string} */
                        status: "pending" | "settled";
                    };
                };
            };
            401: components["responses"]["Unauthenticated"];
            403: components["responses"]["OperatorForbidden"];
            /** @description The reference is invalid or no eligible unresolved attempt with that reference belongs to the manager's store. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description The last verification claim is less than 60 seconds old (payment_check_cooldown), or the provider payment does not match the stored attempt (payment_mismatch). */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["ProblemDetails"];
                };
            };
            503: components["responses"]["ServiceUnavailable"];
        };
    };
